/* Whole-word practice: copy, recall, check, then a complete word test. */
(()=>{'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),D=window.HANZI_PAPER_DATA,C=HanziPaperCore.create(D),KEY='hanzi-paper-v1';
let data=C.fresh(),db=null,opened=false,active=null,audio=null,saveQueue=Promise.resolve(),loaded=false,audioToken=0,lastView=null,lastSpoken=null,selectedRound=null,passive=false;
const host=document.createElement('section');host.id='paper-studio';host.hidden=true;$('#workspace').after(host);
const nav=$('#nav-dictation');nav.textContent='Write words';nav.onclick=show;
function activeRound(){const parent=data.sessions[active];return parent?.relearn||parent;}
function notice(s){$('#paper-save')?.replaceChildren(document.createTextNode(s));}
function save(){if(!loaded||passive)return Promise.resolve();data.activeKey=active;try{if(active)localStorage.setItem('hanzi-paper-active',active);else localStorage.removeItem('hanzi-paper-active');}catch{}const json=JSON.stringify(data);let local=false;try{localStorage.setItem(KEY,json);local=true;}catch{}saveQueue=saveQueue.catch(()=>{}).then(()=>new Promise(resolve=>{if(!db){notice(local?'Saved on this device':'Saving unavailable. Export a backup before leaving.');resolve();return;}try{const tx=db.transaction('progress','readwrite');tx.objectStore('progress').put(JSON.parse(json),'paper-practice');tx.oncomplete=()=>{notice('Saved on this device');resolve();};tx.onabort=tx.onerror=()=>{notice(local?'Saved in browser storage':'Could not save. Export a backup.');resolve();};}catch{notice(local?'Saved in browser storage':'Could not save. Export a backup.');resolve();}}));return saveQueue;}
function stop(){audioToken++;if(audio){audio.pause();audio.onended=null;audio.onerror=null;audio=null;}}
function close(){if(!opened)return;const r=activeRound();if(r){C.pause(r);r.paused=true;r.testPaused=true;}save();stop();lastSpoken=null;opened=false;host.hidden=true;nav.classList.remove('active');try{localStorage.setItem('hanzi-paper-open','false');}catch{}}
function show(){window.HanziPractice?.close();window.HanziVoice?.stop();opened=true;host.hidden=false;$('#workspace').hidden=true;$('.intro').hidden=true;$('#nav-read').classList.remove('active');nav.classList.add('active');try{localStorage.setItem('hanzi-paper-open','true');}catch{}render();}
for(const id of ['nav-read','nav-match'])$('#'+id).addEventListener('click',close);
$('#lesson-list').addEventListener('click',e=>{if(e.target.closest('[data-lesson]'))close();});
const item=id=>C.bank.get(id),time=n=>{const seconds=Math.ceil(n/1000);return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;};
function top(r){return r?`<div class="desk-toolbar"><button data-action="library">← Chapters</button><div>${r.practiceOnly?(C.canTest(r)&&r.stage==='ready'?'':'<button data-action="return-saved">Return to saved activity →</button>'):r.phase!=='study'?'<button data-action="learn-again">← Learn words</button>':''}</div></div>`:'<div class="paper-heading"><h2>Write Hanzi</h2></div>';}
function backup(){return '<details class="paper-backup"><summary>Back up progress</summary><button data-action="export">Export progress</button><button data-action="import">Import backup</button></details>';}
function recommend(c){const existing=Object.entries(data.sessions).filter(([key,r])=>key.startsWith(c.number+'-')&&r.phase!=='complete');if(existing.length)return existing.find(([,r])=>r.phase==='test'||r.phase==='review')?.[0]||existing[0][0];const known=new Set(data.knownWords.map(id=>item(id)?.text));const i=c.words.findIndex(id=>!known.has(item(id).text));return c.number+'-'+Math.floor(Math.max(0,i)/10);}
function library(){const c=D.chapters[data.chapter-1],key=selectedRound?.startsWith(c.number+'-')?selectedRound:recommend(c),b=Number(key.split('-')[1]),r=data.sessions[key],ids=r?.words||c.words.slice(b*10,b*10+10),known=new Set(data.knownWords.map(id=>item(id)?.text)),learned=c.words.filter(id=>known.has(item(id).text)).length;return `<article class="practice-paper chapter-desk"><label class="paper-select">Chapter<select id="paper-chapter">${D.chapters.map(c=>`<option value="${c.number}">${c.number} · ${esc(c.title)}</option>`).join('')}</select></label><div class="chapter-total"><strong>${c.words.length} words</strong><span>New vocabulary + dialogue review</span></div><progress value="${learned}" max="${c.words.length}" aria-label="Chapter words practised"></progress><p class="chapter-progress">${learned} of ${c.words.length} practised</p><div class="next-round"><span>${r?.legacyCoverage?'Your saved round':`Words ${b*10+1}–${Math.min((b+1)*10,c.words.length)} of ${c.words.length}`}</span><button data-open-round="${key}" class="primary">${r?.relearn?'Continue learning':r?.phase==='test'?'Resume test':r?.phase==='review'?'Check answers':r?.phase==='complete'?'View result':r?'Continue practice':'Start practice'} →</button>${r&&r.phase!=='study'?`<button data-learn-round="${key}" class="text-action">Learn these words again</button>`:''}<p>Up to 10 words per round. Every chapter word is included.</p></div><details class="chapter-word-list"><summary>View all ${c.words.length} words</summary><ol>${c.words.map(id=>{const w=item(id);return `<li><b lang="zh-Hans">${esc(w.text)}</b><span>${esc(w.pinyin)}</span>${c.newWords.includes(id)?'<small>New</small>':''}</li>`;}).join('')}</ol></details><details class="round-picker"><summary>Choose another round</summary><label>Practice round<select id="paper-round">${r?.legacyCoverage?`<option value="${key}">Saved previous round</option>`:''}${Array.from({length:Math.ceil(c.words.length/10)},(_,b)=>`<option value="${c.number}-${b}">Words ${b*10+1}–${Math.min((b+1)*10,c.words.length)}</option>`).join('')}</select></label></details><details class="paper-settings"><summary>Practice settings</summary>${data.chapter>5?`<label><input id="paper-phrases" type="checkbox" ${data.phrases?'checked':''}> Include familiar phrases in the test</label>`:''}<p>Timing follows the total strokes in the word: up to 20 strokes = 1 minute; 21–35 = 2; more than 35 = 3.</p><label>Already know the dialogue characters through chapter<select id="known-through">${D.chapters.filter(c=>c.number<data.chapter).map(c=>`<option value="${c.number}">${c.number}</option>`).join('')}</select></label><button data-action="known" ${data.chapter===1?'disabled':''}>Mark earlier characters known</button></details></article>`;}
function study(r){const pool=C.practiceIds(r),w=item(pool[r.index]),hidden=r.stage==='recall',all=C.canTest(r)&&r.stage==='ready';return `<article class="practice-paper clean-practice"><div class="clean-meta"><span>Chapter ${data.chapter}${r.reviewIds?.length?' · Missed words':''}</span><span>${all?`${pool.length} words`:`Word ${r.index+1} of ${pool.length}`}</span>${!all?`<strong id="paper-clock" role="timer">${time(C.remaining(r))}</strong>`:''}</div><progress value="${r.done.length}" max="${pool.length}" aria-label="Words practised"></progress>${all?`<div class="clean-ready">${r.practiceOnly?'<h3>Practice complete</h3><button data-action="return-saved" class="primary">Return to saved activity →</button>':`<h3>Get your paper ready</h3><strong id="prep-clock" role="timer">${Math.ceil((r.prepDeadline?Math.max(0,r.prepDeadline-Date.now()):r.prepRemaining??10000)/1000)}</strong><p>Your test starts automatically.</p><button data-action="timer">${r.paused?'▶ Resume':'Ⅱ Pause'}</button>`}</div>`:`<div class="clean-word-area"><div class="paper-word-model ${hidden?'is-covered':''}" lang="zh-Hans" aria-label="${hidden?'Word hidden':esc(w.text)}">${hidden?'<span class="word-covered">Write from memory</span>':esc(w.text)}</div><p class="paper-reading">${esc(w.pinyin)}</p>${w.meaning?`<p class="clean-meaning">${esc(w.meaning)}</p>`:''}<p class="clean-cue">${hidden?'Write from pinyin. The next word starts automatically.':'Copy the whole word. Hanzi hides halfway.'}</p></div><div class="clean-controls"><button data-action="study-audio">▶ Listen</button><button data-action="timer" class="primary">${r.paused?'▶ Resume':'Ⅱ Pause'}</button></div><div id="paper-player"></div><p id="paper-audio-status" role="status"></p><p id="timer-status" role="status">${r.paused?'Paused · your place is saved.':''}</p><details class="word-options"><summary>Word options</summary><button data-action="restart-word">Restart word</button><button data-action="study-previous" ${!r.index?'disabled':''}>Previous word</button><p>${w.strokes} strokes · ${r.duration/60000} minute${r.duration>60000?'s':''}</p></details>`}</article>`;}
function speed(){return '<label class="paper-speed">Playback<select id="paper-speed"><option value="0.55">Very slow</option><option value="0.65">Slow</option><option value="0.8">Steady</option><option value="1">Original</option></select></label>';}
function test(r){const i=r.testIndex,w=item(r.test[i]),left=r.testDeadline?Math.max(0,r.testDeadline-Date.now()):r.testRemaining??15000;return `<article class="practice-paper paper-test"><div class="clean-meta"><span>Chapter ${data.chapter} · Test</span><span>${i+1} of ${r.test.length}</span><strong id="test-clock" role="timer">${Math.ceil(left/1000)}s</strong></div><progress value="${r.written.length}" max="${r.test.length}" aria-label="Test progress"></progress><h3 class="paper-prompt">${esc(w.pinyin)}</h3>${w.meaning?`<p class="word-test-meaning">${esc(w.meaning)}</p>`:''}<p class="clean-cue">Write answer ${i+1} on paper. Hanzi appears at the end.</p><div class="clean-controls"><button data-action="test-audio">↺ Replay</button><button data-action="test-pause" class="primary">${r.testPaused?'▶ Resume test':'Ⅱ Pause test'}</button></div><div id="paper-player"></div><p id="paper-audio-status" role="status">${r.testPaused?'Paused.':''}</p><details class="test-options"><summary>Audio options</summary>${speed()}</details></article>`;}
function review(r){const total=r.test.length;return `<article class="practice-paper paper-review"><span class="eyebrow">CHECK YOUR PAPER</span><h3>Check your paper</h3><p>Mark each answer, then save your result.</p><ol class="paper-answers">${r.test.map((id,i)=>{const w=item(id);return `<li><div><strong lang="zh-Hans">${esc(w.text)}</strong><span>${esc(w.pinyin)}${w.meaning?' · '+esc(w.meaning):''}</span></div><div class="paper-mark" role="group" aria-label="Mark answer ${i+1}"><button data-mark="${i}" data-value="true" aria-pressed="${r.marks[i]===true}">✓ Correct</button><button data-mark="${i}" data-value="false" aria-pressed="${r.marks[i]===false}">↺ Again</button></div></li>`;}).join('')}</ol><button data-action="finish" class="primary" ${Object.keys(r.marks).length!==total?'disabled':''}>Save result →</button><p class="hint">Self-check only: the app does not read your handwriting.</p></article>`;}
function result(r){const missed=r.test.filter((_,i)=>!r.marks[i]);return `<article class="practice-paper paper-result"><span class="eyebrow">WORD PRACTICE SAVED</span><h3>${Object.values(r.marks).filter(Boolean).length}<small> / ${r.test.length} self-checked</small></h3><p>${r.test.length} writing items tested · ${r.reviewIds?.length?'missed-item review':'whole-word practice'}.</p><details><summary>View answers</summary><div class="paper-result-items">${r.test.map((id,i)=>`<p><b lang="zh-Hans">${esc(item(id).text)}</b><span>${r.marks[i]?'✓ Correct':'↺ Again'}</span></p>`).join('')}</div></details><div class="paper-actions">${missed.length?`<button data-action="review-wrong" class="primary">Practise ${missed.length} missed ${missed.length===1?'item':'items'} →</button>`:''}<button data-action="next-set" class="${missed.length?'':'primary'}">Back to chapter →</button><button data-action="retry">Retake word test</button></div></article>`;}
function render(){if(!opened)return;if(!loaded){host.innerHTML='<p role="status">Loading saved paper practice…</p>';return;}const r=activeRound();if(r?.phase==='study'&&!passive){const started=C.startClock(r),changed=C.tick(data,r);if(started||changed)save();}const view=active+':'+(r?.phase||'library')+(r?.practiceOnly?':relearn':'');host.innerHTML=top(r)+(r?r.phase==='study'?study(r):r.phase==='test'?test(r):r.phase==='review'?review(r):result(r):library())+'<p id="paper-save" role="status">Saved on this device</p>'+backup();bind();if(r?.phase==='test'&&!r.testPaused&&!passive){const speechKey=active+':'+r.test.join('|')+':'+r.testIndex;if(lastSpoken!==speechKey){lastSpoken=speechKey;play(item(r.test[r.testIndex]),true);}}if(view!==lastView){host.scrollIntoView({block:'start',behavior:'instant'});lastView=view;}}
async function play(w,automatic=false){stop();window.HanziVoice?.stop();const own=audioToken,r=data.sessions[active];audio=document.createElement('audio');audio.src=w.audio;audio.controls=false;audio.hidden=true;audio.setAttribute('aria-label','Mandarin practice recording');$('#paper-player').replaceChildren(audio);audio.playbackRate=data.speed;audio.preservesPitch=true;const status=$('#paper-audio-status')||$('#timer-status');status.textContent='Playing slowly…';const fail=()=>{if(own!==audioToken)return;if(automatic&&r?.phase==='test'){C.pause(r);r.testPaused=true;lastSpoken=null;save();render();$('#paper-audio-status').textContent='Audio needs your attention. Press Resume test to try again.';}else status.textContent='Audio could not play. Try replaying the word.';};audio.onerror=fail;audio.onended=()=>{if(own===audioToken)status.textContent='Recording finished. Keep writing; the next prompt will appear automatically.';};try{await audio.play();if(own===audioToken&&automatic&&r?.phase==='test'){C.startTestClock(r);save();}}catch{fail();}}
function bind(){const r=activeRound();if($('#paper-round')){$('#paper-round').value=selectedRound||recommend(D.chapters[data.chapter-1]);$('#paper-round').onchange=e=>{selectedRound=e.target.value;render();};}if($('#paper-phrases'))$('#paper-phrases').onchange=e=>{data.phrases=e.target.checked;save();};if($('#paper-chapter')){$('#paper-chapter').value=String(data.chapter);$('#paper-chapter').onchange=e=>{data.chapter=Number(e.target.value);selectedRound=null;active=null;save();render();};}if($('#known-through'))$('#known-through').value=String(data.chapter-1);if($('#paper-speed')){$('#paper-speed').value=String(data.speed);$('#paper-speed').onchange=e=>{data.speed=Number(e.target.value);if(audio)audio.playbackRate=data.speed;save();};}
host.querySelectorAll('[data-open-round]').forEach(b=>b.onclick=()=>{stop();active=b.dataset.openRound;const round=C.begin(data,data.chapter,Number(active.split('-')[1]));(round.relearn||round).paused=false;if(round.phase==='test'&&!round.relearn)round.testPaused=false;save();render();});
host.querySelectorAll('[data-learn-round]').forEach(b=>b.onclick=()=>{stop();active=b.dataset.learnRound;C.backToLearning(data,data.sessions[active]);lastSpoken=null;save();render();});
host.querySelectorAll('[data-batch]').forEach(b=>b.onclick=()=>{active=data.chapter+'-'+b.dataset.batch;C.begin(data,data.chapter,Number(b.dataset.batch)).paused=false;save();render();});
host.querySelectorAll('[data-relearn-batch]').forEach(b=>b.onclick=()=>{stop();active=data.chapter+'-'+b.dataset.relearnBatch;C.backToLearning(data,data.sessions[active]);lastSpoken=null;save();render();});
host.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{stop();r.testIndex=Number(b.dataset.prompt);save();render();});
host.querySelectorAll('[data-mark]').forEach(b=>b.onclick=()=>{r.marks[b.dataset.mark]=b.dataset.value==='true';save();render();});
host.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==='export'){$('#export-progress').click();return;}if(a==='import'){$('#import-progress').click();return;}if(a==='study-audio'){play(item(C.practiceIds(r)[r.index]));return;}if(a==='test-audio'){if(r.testPaused){r.testPaused=false;lastSpoken=null;render();}else play(item(r.test[r.testIndex]),true);return;}stop();if(a==='library'){if(r){C.pause(r);r.paused=true;r.testPaused=true;}lastSpoken=null;active=null;}else if(a==='known'){const n=Number($('#known-through').value);data.known=[...new Set([...data.known,...D.chapters.filter(c=>c.number<=n).flatMap(c=>c.dialogueCharacters)])];}else if(a==='learn-again'){C.backToLearning(data,data.sessions[active]);lastSpoken=null;}else if(a==='return-saved'){C.pause(r);C.returnFromLearning(data.sessions[active]);lastSpoken=null;}else if(a==='review-wrong'){C.reviewWrong(data,r);lastSpoken=null;}else if(a==='test-pause'){C.pause(r);r.testPaused=!r.testPaused;lastSpoken=null;}else if(a==='timer'){if(r.paused){r.paused=false;C.startClock(r);}else{C.pause(r);r.paused=true;}}else if(a==='restart-word'){C.restart(data,r);}else if(a==='hide-word'){r.stage='recall';}else if(a==='show-word'){r.stage='compare';}else if(a==='again'){r.stage='copy';}else if(a==='study-previous'){C.pause(r);r.index=Math.max(0,r.index-1);C.restart(data,r);}else if(a==='done'){C.done(data,r);}else if(a==='next-set'){active=null;selectedRound=null;}else if(a==='test'||a==='retry'){try{C.tests(data,r,data.chapter);}catch(e){notice(e.message);return;}}else if(a==='previous'){r.testIndex=Math.max(0,r.testIndex-1);}else if(a==='written'){if(!r.written.includes(r.testIndex))r.written.push(r.testIndex);const next=r.test.findIndex((_,i)=>i>r.testIndex&&!r.written.includes(i));if(next>=0)r.testIndex=next;else{const any=r.test.findIndex((_,i)=>!r.written.includes(i));if(any>=0)r.testIndex=any;}}else if(a==='reveal'){C.reveal(r);}else if(a==='finish'){C.finish(data,r,active);}save();render();});}
setInterval(()=>{if(!opened||passive)return;const r=activeRound();if(!r)return;let changed=false;if(r.phase==='study'&&!r.paused){changed=C.tick(data,r);if($('#paper-clock'))$('#paper-clock').textContent=time(C.remaining(r));if($('#prep-clock'))$('#prep-clock').textContent=String(Math.ceil((r.prepDeadline?Math.max(0,r.prepDeadline-Date.now()):r.prepRemaining??10000)/1000));}else if(r.phase==='test'&&!r.testPaused){changed=C.tickTest(r);if($('#test-clock'))$('#test-clock').textContent=String(Math.ceil((r.testDeadline?Math.max(0,r.testDeadline-Date.now()):r.testRemaining??15000)/1000))+'s';}if(changed){stop();lastSpoken=null;save();render();}},250);
const ready=(async()=>{try{db=await new Promise((resolve,reject)=>{const q=indexedDB.open('hanzi-reading-room',1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('progress'))q.result.createObjectStore('progress');};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}catch{}let raw;try{raw=JSON.parse(localStorage.getItem(KEY));}catch{}if(!raw&&db)raw=await new Promise(resolve=>{const q=db.transaction('progress').objectStore('progress').get('paper-practice');q.onsuccess=()=>resolve(q.result);q.onerror=()=>resolve(null);});data=C.clean(raw);try{const savedKey=data.activeKey||localStorage.getItem('hanzi-paper-active'),key=data.sessionAliases[savedKey]||savedKey;if(data.sessions[key]&&Number(key.split('-')[0])===data.chapter)active=key;}catch{}loaded=true;save();if(opened)render();return data;})();
window.HanziPaper={ready,refresh:()=>{if(opened)show();},snapshot:()=>JSON.parse(JSON.stringify(data)),clean:C.clean,importData:async raw=>{await ready;stop();data=C.clean(raw);active=null;await save();if(opened)render();},show,close};
try{if(localStorage.getItem('hanzi-paper-open')==='true')show();else if(localStorage.getItem('hanzi-practice-open')==='true'&&window.HanziPractice?.snapshot().kind==='dictation')show();}catch{}
function pauseAway(){stop();if(passive)return;lastSpoken=null;const r=activeRound();if(loaded&&r&&(r.phase==='study'||r.phase==='test')){C.pause(r);r.paused=true;r.testPaused=true;save();if(opened)render();}}
function claim(redraw=true){if(!passive)return;passive=false;lastSpoken=null;save();if(opened&&redraw)render();}
host.addEventListener('pointerdown',()=>claim(false),{capture:true});nav.addEventListener('pointerdown',()=>claim(false),{capture:true});
window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue||!loaded)return;try{stop();lastSpoken=null;data=C.clean(JSON.parse(e.newValue));active=data.activeKey;selectedRound=null;passive=true;if(opened)render();}catch{}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseAway();else claim();});window.addEventListener('pagehide',pauseAway);
})();
